actions.script:
ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").list().each {
    it.set("enabled", "N").store()
}
def existing = ec.entity.find("moqui.adk.AdkAgentConfig").condition("agentName", agentName).one()
if (existing) {
    existing.set("modelName", modelName).set("apiKey", apiKey)
        .set("instruction", instruction).set("description", description)
        .set("enabled", "Y").store()
} else {
    ec.entity.makeValue("moqui.adk.AdkAgentConfig")
        .setSequencedIdPrimary()
        .set("agentName",   agentName   ?: "MoquiAgent")
        .set("modelName",   modelName   ?: "gemini-2.0-flash")
        .set("apiKey",      apiKey)
        .set("instruction", instruction ?: "You are a helpful assistant for the GrowERP ERP system.")
        .set("description", description ?: "ADK Agent")
        .set("enabled", "Y")
        .create()
}

import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse

boolean wasDisabled = ec.artifactExecution.disableAuthz()
def cfg
try {
    cfg = ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").one()
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

String apiKey   = cfg?.apiKey   ?: ""
String model    = cfg?.modelName ?: "gemini-2.0-flash"
String sysInstr = cfg?.instruction ?: ""

if (!apiKey) { response = "[Error: no API key configured — go to ADK → Configuration]"; return }

// Retrieve or initialise session history
def history = org.moqui.adk.AdkSessionHolder.sessions.computeIfAbsent(sessionId, { [] })
history << [role: "user", parts: [[text: message]]]

def bodyMap = [contents: history]
if (sysInstr) bodyMap['system_instruction'] = [parts: [[text: sysInstr]]]

def client  = HttpClient.newHttpClient()
def request = HttpRequest.newBuilder()
    .uri(URI.create("https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}"))
    .header("Content-Type", "application/json")
    .POST(HttpRequest.BodyPublishers.ofString(JsonOutput.toJson(bodyMap)))
    .build()

def httpResp = client.send(request, HttpResponse.BodyHandlers.ofString())
def parsed   = new JsonSlurper().parseText(httpResp.body())

response = parsed?.candidates?.getAt(0)?.content?.parts?.getAt(0)?.text ?: ""
if (!response && parsed?.error) response = "[Gemini error: ${parsed.error.message}]"

// Append model reply to history for multi-turn context
if (response) history << [role: "model", parts: [[text: response]]]
